(() => {
"use strict";
/**
 * AunuCore youtube gift (phase test #5) — GIF button + picker
 * ============================================================
 * File ini menambah UI yang tidak ada di phase test #1:
 * 1) Tombol "GIF" yang disisipkan ke kotak komentar YouTube desktop
 *    (ytd-comment-simplebox-renderer).
 * 2) Panel picker: cari GIF di Tenor TANPA API key pribadi — sejak
 *    phase #3 pencarian berjalan lewat service worker (sw.js) yang
 *    memakai key situs tenor.com sendiri, seperti ekstensi
 *    desktop_gifs. Alternatif: tempel URL GIF langsung.
 *    PICKER_CONFIG.tenorApiKey kini hanya override opsional developer.
 * 3) GIF terpilih disimpan di pickerState.selected dan diumumkan lewat
 *    CustomEvent "aunucore:gif-selected" — main.js mendengarkannya dan
 *    menyimpannya sebagai pendingGif untuk interceptor.
 *
 * BATAS SAAT INI: memilih GIF belum melampirkannya ke komentar.
 * Lampiran aktif setelah resolver upload (phase test #5) selesai.
 * ============================================================
 */

// ---------------------------------------------------------------------------
// Konfigurasi
// ---------------------------------------------------------------------------

const PICKER_CONFIG = {
  // Isi dengan Tenor API key milikmu (https://developers.google.com/tenor)
  // agar pencarian GIF di panel aktif. Kosong = pencarian Tenor nonaktif,
  // mode "tempel URL GIF langsung" tetap bisa dipakai.
  tenorApiKey: "",
  tenorClientKey: "aunucore_youtube_gift",
  resultLimit: 24,
};

function resolveTenorApiKey(config = {}) {
  const fromWindow =
    typeof window !== "undefined"
      ? window.__AUNUCORE_YT_GIFT_CONFIG__?.tenorApiKey
      : undefined;
  return config.tenorApiKey || fromWindow || PICKER_CONFIG.tenorApiKey || "";
}

const TENOR_BASE = "https://tenor.googleapis.com/v2";

// ---------------------------------------------------------------------------
// Helper murni (aman diuji node --test)
// ---------------------------------------------------------------------------

function buildTenorSearchUrl({ q, apiKey, limit = 24, pos = "" } = {}) {
  const params = new URLSearchParams({
    q: String(q ?? ""),
    key: String(apiKey ?? ""),
    client_key: PICKER_CONFIG.tenorClientKey,
    limit: String(limit),
    media_filter: "gif,tinygif,nanogif",
  });
  if (pos) params.set("pos", String(pos));
  return `${TENOR_BASE}/search?${params.toString()}`;
}

function buildTenorFeaturedUrl({ apiKey, limit = 24, pos = "" } = {}) {
  const params = new URLSearchParams({
    key: String(apiKey ?? ""),
    client_key: PICKER_CONFIG.tenorClientKey,
    limit: String(limit),
    media_filter: "gif,tinygif,nanogif",
  });
  if (pos) params.set("pos", String(pos));
  return `${TENOR_BASE}/featured?${params.toString()}`;
}

function normalizeTenorResults(json) {
  const results = Array.isArray(json?.results) ? json.results : [];
  const out = [];
  for (const item of results) {
    const formats = item?.media_formats ?? {};
    const gifUrl = formats.gif?.url;
    if (!gifUrl) continue;
    out.push({
      id: String(item.id ?? gifUrl),
      title: String(item.title ?? item.content_description ?? "GIF"),
      gifUrl,
      previewUrl: formats.tinygif?.url ?? formats.nanogif?.url ?? gifUrl,
      width: formats.gif?.dims?.[0] ?? null,
      height: formats.gif?.dims?.[1] ?? null,
      source: "tenor",
    });
  }
  return out;
}

function isDirectGifUrl(value) {
  try {
    const url = new URL(String(value ?? "").trim());
    if (!/^https?:$/.test(url.protocol)) return false;
    return /\.(gif|webp)(\?.*)?$/i.test(url.pathname + url.search) || /\.(gif|webp)$/i.test(url.pathname);
  } catch {
    return false;
  }
}

function gifFromDirectUrl(value) {
  const url = String(value ?? "").trim();
  if (!isDirectGifUrl(url)) return null;
  return { id: url, title: "GIF dari URL langsung", gifUrl: url, previewUrl: url, width: null, height: null, source: "direct-url" };
}

// ---------------------------------------------------------------------------
// Pencarian lewat service worker (jalur utama sejak phase #3)
// ---------------------------------------------------------------------------

let bridgeSeq = 0;

function requestViaBridge({ type, query = "", win, timeoutMs = 12000 } = {}) {
  const windowRef = win ?? (typeof window !== "undefined" ? window : null);
  if (!windowRef?.postMessage || !windowRef?.addEventListener) {
    return Promise.reject(new Error("Bridge tidak tersedia di konteks ini"));
  }
  const requestId = `ac-${Date.now()}-${++bridgeSeq}`;
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error("Service worker tidak menjawab (timeout) — coba reload ekstensi"));
    }, timeoutMs);
    const onMessage = (event) => {
      const data = event.data;
      if (!data || data.source !== "aunucore-bridge" || data.type !== "RESULT" || data.requestId !== requestId) return;
      cleanup();
      if (data.ok) resolve(Array.isArray(data.gifs) ? data.gifs : []);
      else reject(new Error(data.error ?? "Pencarian gagal"));
    };
    const cleanup = () => {
      clearTimeout(timer);
      windowRef.removeEventListener("message", onMessage);
    };
    windowRef.addEventListener("message", onMessage);
    windowRef.postMessage(
      { source: "aunucore-main", type, requestId, query },
      windowRef.location?.origin ?? "*",
    );
  });
}

async function browserBridgeSearch(query) {
  return requestViaBridge({ type: query ? "SEARCH" : "FEATURED", query });
}

/**
 * Pencarian GIF untuk UI. Urutan jalur:
 * 1) bridgeSearch yang di-inject (test / pemanggil khusus)
 * 2) API key pribadi bila developer mengisinya (override langsung)
 * 3) service worker via bridge (key situs tenor.com) — jalur normal
 */
async function searchGifs({ q, apiKey, fetchImpl, bridgeSearch } = {}) {
  if (typeof bridgeSearch === "function") return bridgeSearch(q ?? "");
  const key = resolveTenorApiKey({ tenorApiKey: apiKey });
  if (key) return searchTenor({ q, apiKey: key, fetchImpl });
  return browserBridgeSearch(q ?? "");
}

// ---------------------------------------------------------------------------
// State pemilihan GIF
// ---------------------------------------------------------------------------

function createPickerState() {
  return { selected: null, isOpen: false, lastQuery: "", results: [], lastPostResult: null };
}

/** Ubah putusan interceptor (phase test #5) menjadi teks status panel. */
function messageForPostResult(detail) {
  if (!detail) return "";
  switch (detail.kind) {
    case "posted":
      return "GIF berhasil terkirim sebagai lampiran komentar.";
    case "blocked":
      return `YouTube menolak komentar GIF dari desktop setelah ${detail.tries ?? "?"} percobaan — tidak ada yang terkirim. GIF-nya bukan penyebabnya; coba lagi nanti atau pakai aplikasi YouTube di HP.`;
    case "gif":
      return "YouTube menolak GIF ini (kemungkinan bukan rating G / tidak dikenal). Pilih GIF lain.";
    case "rejected":
      return `YouTube menolak komentar ini (HTTP ${detail.httpStatus ?? "?"}). Tidak ada yang terkirim.`;
    case "network":
      return "Koneksi gagal saat mengirim — tidak ada yang terkirim.";
    default:
      return "YouTube tidak memberi konfirmasi jelas. Cek daftar komentar sebelum mencoba lagi.";
  }
}

const pickerState = createPickerState();

function selectGif(state, gif) {
  if (!gif?.gifUrl) return state;
  state.selected = gif;
  return state;
}

function clearSelectedGif(state) {
  state.selected = null;
  return state;
}

async function searchTenor({ q, apiKey, fetchImpl } = {}) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== "function") throw new Error("fetch tidak tersedia");
  const key = resolveTenorApiKey({ tenorApiKey: apiKey });
  if (!key) {
    const err = new Error("TENOR_API_KEY kosong — isi PICKER_CONFIG.tenorApiKey di extension/src/picker.js");
    err.code = "NO_API_KEY";
    throw err;
  }
  const url = q
    ? buildTenorSearchUrl({ q, apiKey: key, limit: PICKER_CONFIG.resultLimit })
    : buildTenorFeaturedUrl({ apiKey: key, limit: PICKER_CONFIG.resultLimit });
  const res = await doFetch(url);
  if (!res?.ok) throw new Error(`Tenor API gagal: HTTP ${res?.status ?? "?"}`);
  return normalizeTenorResults(await res.json());
}

// ---------------------------------------------------------------------------
// UI (browser saja) — tombol GIF + panel picker
// ---------------------------------------------------------------------------

const BUTTON_MARK = "data-aunucore-gif-btn";
const PANEL_ID = "aunucore-gif-panel";
const STYLE_ID = "aunucore-gif-style";

function ensureStyles(doc) {
  if (doc.getElementById(STYLE_ID)) return;
  const style = doc.createElement("style");
  style.id = STYLE_ID;
  style.textContent = `
    .aunucore-gif-btn{cursor:pointer;border:1px solid var(--yt-spec-10-percent-layer,rgba(0,0,0,.2));
      background:transparent;color:inherit;border-radius:12px;padding:2px 10px;margin:0 4px;
      font-size:12px;font-weight:700;letter-spacing:.5px;line-height:22px}
    .aunucore-gif-btn:hover{background:var(--yt-spec-10-percent-layer,rgba(0,0,0,.08))}
    #${PANEL_ID}{position:relative;z-index:50;margin:8px 0;padding:10px;border-radius:12px;
      border:1px solid var(--yt-spec-10-percent-layer,rgba(0,0,0,.2));
      background:var(--yt-spec-menu-background,#fff);color:var(--yt-spec-text-primary,#0f0f0f);
      max-width:560px;box-shadow:0 4px 16px rgba(0,0,0,.18)}
    #${PANEL_ID} .ac-head{display:flex;justify-content:space-between;align-items:center;font-weight:700;font-size:13px;margin-bottom:8px}
    #${PANEL_ID} .ac-row{display:flex;gap:6px;margin-bottom:8px}
    #${PANEL_ID} input{flex:1;padding:6px 8px;border-radius:8px;border:1px solid var(--yt-spec-10-percent-layer,rgba(0,0,0,.25));background:transparent;color:inherit}
    #${PANEL_ID} button.ac-act{cursor:pointer;padding:6px 12px;border-radius:8px;border:1px solid var(--yt-spec-10-percent-layer,rgba(0,0,0,.25));background:transparent;color:inherit;font-weight:600}
    #${PANEL_ID} .ac-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;max-height:320px;overflow:auto}
    #${PANEL_ID} .ac-grid img{width:100%;height:88px;object-fit:cover;border-radius:8px;cursor:pointer}
    #${PANEL_ID} .ac-grid img:hover{outline:2px solid #3ea6ff}
    #${PANEL_ID} .ac-status{font-size:12px;opacity:.85;min-height:16px}
    #${PANEL_ID} .ac-selected{display:flex;gap:8px;align-items:center;font-size:12px;margin-top:8px}
    #${PANEL_ID} .ac-selected img{width:64px;height:48px;object-fit:cover;border-radius:6px}
  `;
  doc.head.appendChild(style);
}

function buildPanel(doc, win, logger) {
  // PENTING: panel dibangun 100% dengan DOM API, TANPA innerHTML.
  // YouTube memberlakukan Trusted Types ("require-trusted-types"),
  // sehingga assignment innerHTML dari halaman akan ditolak dengan
  // "This document requires 'TrustedHTML' assignment". createElement
  // + textContent tidak termasuk sink yang dibatasi.
  const el = (tag, cls, text) => {
    const node = doc.createElement(tag);
    if (cls) node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  };
  const actBtn = (ac, text) => {
    const b = el("button", "ac-act", text);
    b.type = "button";
    b.setAttribute("data-ac", ac);
    return b;
  };
  const field = (ac, placeholder) => {
    const i = el("input");
    i.type = "text";
    i.setAttribute("data-ac", ac);
    i.placeholder = placeholder;
    return i;
  };
  const slot = (tag, cls, ac) => {
    const n = el(tag, cls);
    n.setAttribute("data-ac", ac);
    return n;
  };

  const panel = el("div");
  panel.id = PANEL_ID;

  const head = el("div", "ac-head");
  head.append(el("span", null, "GIF — AunuCore youtube gift (phase test #5)"), actBtn("close", "Tutup"));

  const rowSearch = el("div", "ac-row");
  rowSearch.append(field("query", "Cari GIF (Tenor)… lalu Enter"), actBtn("search", "Cari"));

  const rowDirect = el("div", "ac-row");
  rowDirect.append(field("direct", "atau tempel URL .gif/.webp langsung"), actBtn("use-direct", "Pakai URL"));

  panel.append(
    head,
    rowSearch,
    rowDirect,
    slot("div", "ac-status", "status"),
    slot("div", "ac-grid", "grid"),
    slot("div", "ac-selected", "selected"),
  );

  const status = panel.querySelector('[data-ac="status"]');
  const grid = panel.querySelector('[data-ac="grid"]');
  const selectedBox = panel.querySelector('[data-ac="selected"]');
  const queryInput = panel.querySelector('[data-ac="query"]');

  const renderSelected = () => {
    // DOM API saja (tanpa innerHTML) — alasan Trusted Types seperti
    // di buildPanel; juga judul GIF tidak lagi diinterpolasi mentah.
    selectedBox.replaceChildren();
    const gif = pickerState.selected;
    if (!gif) return;
    const img = doc.createElement("img");
    img.src = gif.previewUrl;
    img.alt = "";
    const label = doc.createElement("span");
    const bold = doc.createElement("b");
    bold.textContent = gif.title;
    label.append(
      doc.createTextNode("GIF terpilih: "),
      bold,
      doc.createTextNode(" — akan terlampir sebagai GIF Tenor saat komentar diposting."),
    );
    const clearBtn = doc.createElement("button");
    clearBtn.type = "button";
    clearBtn.className = "ac-act";
    clearBtn.setAttribute("data-ac", "clear");
    clearBtn.textContent = "Hapus";
    clearBtn.addEventListener("click", () => {
      clearSelectedGif(pickerState);
      win.dispatchEvent(new win.CustomEvent("aunucore:gif-cleared", { detail: null }));
      renderSelected();
    });
    selectedBox.append(img, label, clearBtn);
  };

  const pick = (gif) => {
    selectGif(pickerState, gif);
    win.dispatchEvent(new win.CustomEvent("aunucore:gif-selected", { detail: gif }));
    status.textContent = `Terpilih: ${gif.title}`;
    renderSelected();
    logger.info?.(`[AunuCore youtube gift (phase test #5)] GIF terpilih`, gif);
  };

  const renderResults = (gifs) => {
    grid.replaceChildren();
    for (const gif of gifs) {
      const img = doc.createElement("img");
      img.src = gif.previewUrl;
      img.alt = gif.title;
      img.title = gif.title;
      img.loading = "lazy";
      img.addEventListener("click", () => pick(gif));
      grid.appendChild(img);
    }
    status.textContent = gifs.length ? `${gifs.length} GIF — klik untuk memilih` : "Tidak ada hasil.";
  };

  const doSearch = async () => {
    status.textContent = "Mencari…";
    try {
      const gifs = await searchGifs({ q: queryInput.value.trim() });
      pickerState.results = gifs;
      renderResults(gifs);
    } catch (err) {
      status.textContent = `Gagal mencari: ${err.message} — mode tempel URL tetap bisa dipakai.`;
    }
  };

  panel.querySelector('[data-ac="search"]').addEventListener("click", doSearch);
  queryInput.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); doSearch(); } });
  panel.querySelector('[data-ac="close"]').addEventListener("click", () => { panel.remove(); pickerState.isOpen = false; });
  panel.querySelector('[data-ac="use-direct"]').addEventListener("click", () => {
    const value = panel.querySelector('[data-ac="direct"]').value;
    const gif = gifFromDirectUrl(value);
    if (!gif) { status.textContent = "URL tidak valid — harus link langsung berakhiran .gif atau .webp (http/https)."; return; }
    pick(gif);
  });

  // Peringatan jujur (phase test #5): bila hook pengiriman belum
  // live di tab ini (tab termuat sebelum ekstensi aktif), GIF tidak
  // akan terkirim sampai tab di-refresh. Jangan berpura-pura aktif.
  if (win?.__AUNUCORE_YT_GIFT__ && win.__AUNUCORE_YT_GIFT__.hookLive === false) {
    status.textContent =
      "Hook pengiriman belum live di tab ini — refresh halaman ini dulu, lalu pilih GIF lagi.";
  }

  renderSelected();
  return panel;
}

function findToolbar(commentBox) {
  return (
    commentBox.querySelector("#footer") ||
    commentBox.querySelector(".footer") ||
    commentBox.querySelector("#buttons") ||
    commentBox.querySelector("#input-container")?.parentElement ||
    commentBox
  );
}

// Kotak komentar kanonis: #simple-box hidup DI DALAM renderer
// simplebox; memperlakukan keduanya sebagai box terpisah pernah
// menghasilkan dua tombol GIF dalam satu kotak komentar.
function canonicalCommentRoot(box) {
  return box?.closest?.("ytd-comment-simplebox-renderer, ytd-commentbox-renderer") ?? box;
}

function ensureGifButton(commentBox, { doc, win, logger = console } = {}) {
  if (!commentBox) return false;
  const root = canonicalCommentRoot(commentBox);
  if (root.querySelector(`[${BUTTON_MARK}]`)) return false;
  const documentRef = doc ?? root.ownerDocument;
  const windowRef = win ?? documentRef.defaultView;
  ensureStyles(documentRef);

  const btn = documentRef.createElement("button");
  btn.type = "button";
  btn.className = "aunucore-gif-btn";
  btn.setAttribute(BUTTON_MARK, "1");
  btn.textContent = "GIF";
  btn.title = "AunuCore youtube gift (phase test #5) — pilih GIF";
  btn.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    const existing = documentRef.getElementById(PANEL_ID);
    if (existing) { existing.remove(); pickerState.isOpen = false; return; }
    const panel = buildPanel(documentRef, windowRef, logger);
    root.appendChild(panel);
    pickerState.isOpen = true;
  });

  findToolbar(root).appendChild(btn);
  return true;
}

function scanAndInjectButtons({ doc = document, logger = console } = {}) {
  let added = 0;
  // Hanya renderer kanonis. "#simple-box" sengaja TIDAK dicari
  // terpisah: ia anak renderer simplebox (lihat canonicalCommentRoot).
  const boxes = doc.querySelectorAll(
    "ytd-comment-simplebox-renderer, ytd-commentbox-renderer"
  );
  boxes.forEach((box) => { if (ensureGifButton(box, { logger })) added++; });
  return added;
}

function initGifPicker({ win = window, doc = document, logger = console } = {}) {
  if (!doc || !win) return () => {};
  scanAndInjectButtons({ doc, logger });
  const observer = new win.MutationObserver(() => scanAndInjectButtons({ doc, logger }));
  observer.observe(doc.documentElement, { childList: true, subtree: true });
  // Hasil akhir pengiriman komentar GIF dari interceptor (main.js):
  // simpan di state dan tampilkan di panel bila sedang terbuka.
  const onPostResult = (e) => {
    pickerState.lastPostResult = e.detail ?? null;
    const status = doc.querySelector(`#${PANEL_ID} [data-ac="status"]`);
    if (status) status.textContent = messageForPostResult(e.detail);
  };
  win.addEventListener("aunucore:gif-post-result", onPostResult);
  logger.info?.("[AunuCore youtube gift (phase test #5)] tombol GIF + picker aktif");
  return () => {
    observer.disconnect();
    win.removeEventListener("aunucore:gif-post-result", onPostResult);
  };
}

/**
 * AunuCore youtube gift (phase test #3)
 * ============================================================
 * ATURAN PENAMAAN PERCOBAAN:
 * - Setiap percobaan WAJIB ganti nama dengan menaikkan angka di
 *   PHASE_TEST_NUMBER saja. Jangan edit string lain.
 *   #1 -> "AunuCore youtube gift (phase test #1)"
 *   #2 -> "AunuCore youtube gift (phase test #2)"
 *   #3 -> "AunuCore youtube gift (phase test #3)" dst.
 * - BUILD_NAME terbentuk otomatis dari angka itu, dan dipakai di:
 *   console prefix, window.__AUNUCORE_YT_GIFT__, dan log interceptor.
 *   Nama ini TIDAK disuntikkan ke payload YouTube (field asing di
 *   payload berisiko memicu 400 INVALID_ARGUMENT lagi).
 *
 * CATATAN ISSUE #93 (diperbarui di phase test #4):
 * - Sejak 14 Okt 2026, `tenorId` di /comment/create_comment sering
 *   ditolak 400 INVALID_ARGUMENT — tetapi TIDAK selalu: pengukuran
 *   ekstensi referensi desktop_gifs (rayytor), yang source-nya
 *   dipelajari untuk phase ini, menunjukkan penolakan itu tidak
 *   konsisten dan bergantung wilayah koneksi.
 * - Jalur lama phase #1–#3 (buang tenorId + isi
 *   imageAttachment.encryptedBlobId dari upload WebP) DIBUANG:
 *   tidak ada implementasi referensi yang memakainya, dan
 *   encryptedBlobId tidak bisa dibuat/ditebak di client.
 * - Phase #4 memakai jalur yang terbukti: pasang tenorId dari GIF
 *   terpilih, lalu coba ulang request yang ditolak "blocked"
 *   sampai 12x (~30 detik). Request yang ditolak tidak memposting
 *   apa pun, jadi retry tidak bisa memposting dobel.
 * - Semua GIF dari pencarian kita berating G (contentfilter=high
 *   di service worker) — syarat agar retry layak dilakukan.
 * ============================================================
 */


// ---------------------------------------------------------------------------
// 1. Identitas build / penamaan percobaan
// ---------------------------------------------------------------------------

const PHASE_TEST_NUMBER = 5;
const BUILD_NAME_BASE = "AunuCore youtube gift";

function makePhaseTestName(phase = PHASE_TEST_NUMBER) {
  const n = Number.isInteger(phase) && phase > 0 ? phase : 1;
  return `${BUILD_NAME_BASE} (phase test #${n})`;
}

function nextPhaseTestName(currentPhase = PHASE_TEST_NUMBER) {
  return makePhaseTestName(currentPhase + 1);
}

const BUILD_NAME = makePhaseTestName(PHASE_TEST_NUMBER);
const LOG_PREFIX = `[${BUILD_NAME}]`;

// ---------------------------------------------------------------------------
// 2. Deteksi request create_comment
// ---------------------------------------------------------------------------

const CREATE_COMMENT_PATH = "/comment/create_comment";

function isCreateCommentRequest(url) {
  if (!url) return false;
  try {
    const parsed = new URL(String(url), "https://www.youtube.com");
    return parsed.pathname.includes(CREATE_COMMENT_PATH);
  } catch {
    return false;
  }
}

function getRequestUrl(input) {
  if (typeof input === "string") return input;
  if (input instanceof URL) return input.href;
  return input?.url ?? "";
}

function getRequestMethod(input, init = {}) {
  return String(init.method || input?.method || "GET").toUpperCase();
}

// ---------------------------------------------------------------------------
// 3. Transformer payload (PURE - aman diuji dengan node --test)
// ---------------------------------------------------------------------------

function extractTenorId(payload) {
  if (!payload || typeof payload !== "object") return undefined;
  if (typeof payload.tenorId === "string" && payload.tenorId) return payload.tenorId;
  for (const value of Object.values(payload)) {
    if (value && typeof value === "object") {
      const found = extractTenorId(value);
      if (found) return found;
    }
  }
  return undefined;
}

/** ID GIF Tenor yang sah untuk tenorId: string digit (id post Tenor). */
function isTenorPostId(id) {
  return typeof id === "string" && /^\d{1,20}$/.test(id);
}

/**
 * Pasang GIF terpilih ke payload sebagai tenorId (phase test #4).
 * Mengembalikan { payload, armed } — armed=false bila GIF bukan dari
 * Tenor (mis. mode tempel URL langsung): GIF seperti itu tidak punya
 * id Tenor dan tidak bisa dilampirkan lewat jalur ini.
 * Payload asli tidak dimutasi.
 */
function applyGifToPayload(payload, gif) {
  if (!payload || typeof payload !== "object") return { payload, armed: false };
  const next =
    typeof structuredClone === "function"
      ? structuredClone(payload)
      : JSON.parse(JSON.stringify(payload));
  if (!isTenorPostId(gif?.id)) return { payload: next, armed: false };
  next.tenorId = String(gif.id);
  return { payload: next, armed: true };
}

/** Alias transformasi phase #4 (nama lama dipertahankan untuk test lama). */
function transformCreateCommentPayload(payload, { pendingGif } = {}) {
  return applyGifToPayload(payload, pendingGif).payload;
}

/** Contoh payload SEBELUM GIF dipilih — komentar teks biasa. */
function mockPayloadBefore() {
  return {
    context: { client: { clientName: "WEB", clientVersion: "2.20261014" } },
    commentText: "test gif",
    createCommentParams: "Eg0SCw...",
  };
}

/** Contoh payload SESUDAH GIF Tenor dipilih — tenorId terpasang. */
function mockPayloadAfter() {
  return {
    context: { client: { clientName: "WEB", clientVersion: "2.20261014" } },
    commentText: "test gif",
    createCommentParams: "Eg0SCw...",
    tenorId: "13710736021070431175",
  };
}

// ---------------------------------------------------------------------------
// 3b. Pending GIF — GIF yang dipilih dari picker (phase test #2)
// ---------------------------------------------------------------------------

/** Pending GIF kedaluwarsa 3 menit agar tidak menempel ke komentar lain. */
const PENDING_TTL_MS = 3 * 60 * 1000;

let pendingGif = null;
let pendingArmedAt = 0;

function setPendingGif(gif, nowMs = Date.now()) {
  pendingGif = gif?.gifUrl ? gif : null;
  pendingArmedAt = pendingGif ? nowMs : 0;
  return pendingGif;
}

function getPendingGif(nowMs = Date.now()) {
  if (pendingGif && nowMs - pendingArmedAt > PENDING_TTL_MS) {
    pendingGif = null;
    pendingArmedAt = 0;
  }
  return pendingGif;
}

// ---------------------------------------------------------------------------
// 4. Penilaian respons create_comment + jadwal retry (PURE, untuk test)
// ---------------------------------------------------------------------------
// kind:
//   posted    komentar benar-benar terbit (actionResult STATUS_SUCCEEDED)
//   blocked   400 INVALID_ARGUMENT — GIF diterima bentuknya, komentar
//             ditolak; satu-satunya kind yang layak di-retry
//   gif       HTTP 200 tetapi ada showErrorAction: YouTube memeriksa
//             GIF-nya dan menolaknya (id tak dikenal / bukan rating G)
//   rejected  penolakan lain; tidak ada yang terbit
//   uncertain tidak ada konfirmasi yang bisa dibaca

const RETRY_DELAYS_MS = [1000, 1500, 2000, 2000, 2500, 2500, 3000, 3000, 3000, 3000, 3000];
const MAX_TRIES = RETRY_DELAYS_MS.length + 1;

function textOfValue(value) {
  if (typeof value === "string") return value;
  if (!value || typeof value !== "object") return "";
  if (typeof value.simpleText === "string") return value.simpleText;
  if (typeof value.content === "string") return value.content;
  if (Array.isArray(value.runs)) {
    return value.runs.map((r) => (typeof r?.text === "string" ? r.text : "")).join("");
  }
  return "";
}

/** Kumpulkan pesan dari semua showErrorAction (termasuk yang bersarang). */
function collectShowErrorMessages(node, out = [], depth = 0) {
  if (!node || typeof node !== "object" || depth > 8) return out;
  if (Array.isArray(node)) {
    for (const item of node) collectShowErrorMessages(item, out, depth + 1);
    return out;
  }
  if (node.showErrorAction) {
    const err = node.showErrorAction.errorMessage;
    const text = textOfValue(err?.messageRenderer?.text) || textOfValue(err);
    if (text) out.push(text);
  }
  for (const value of Object.values(node)) collectShowErrorMessages(value, out, depth + 1);
  return out;
}

function classifyCommentResponse({ httpStatus, json } = {}) {
  const apiStatus = typeof json?.error?.status === "string" ? json.error.status : null;
  const actionStatus = typeof json?.actionResult?.status === "string" ? json.actionResult.status : null;
  const errors = json ? collectShowErrorMessages(json) : [];
  const message = [...new Set([
    textOfValue(json?.error?.message),
    ...errors,
    textOfValue(json?.actionResult?.feedbackText),
  ].filter(Boolean))].join(" ");

  const kind =
    httpStatus >= 200 && httpStatus < 300 && actionStatus === "STATUS_SUCCEEDED" && errors.length === 0
      ? "posted"
      : httpStatus === 400 && apiStatus === "INVALID_ARGUMENT"
        ? "blocked"
        : errors.length > 0
          ? "gif"
          : httpStatus >= 400
            ? "rejected"
            : "uncertain";

  return { kind, httpStatus, apiStatus, actionStatus, message };
}

async function judgeCommentResponse(response) {
  let json = null;
  try {
    json = await response.clone().json();
  } catch {
    /* respons tidak terbaca -> tidak mengonfirmasi apa pun */
  }
  return classifyCommentResponse({ httpStatus: response?.status ?? 0, json });
}

const defaultSleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// ---------------------------------------------------------------------------
// 5. Fetch interceptor (side-effect browser saja)
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// 5b. Hook persisten pada window.fetch (phase test #5)
// ---------------------------------------------------------------------------
// Wrapper dipasang SEKALI pada window.fetch dan mendelegasikan ke
// handler terbaru (slot.current). Salinan bundle yang lebih baru
// mempensiunkan handler lama lewat teardown-nya — satu halaman tidak
// pernah punya dua interceptor bertumpuk dengan state terpisah.
//
// Kenapa perlu: di phase test #4 terbukti request create_comment
// lolos sebagai fetch 200 biasa dari script YouTube (200.js) tanpa
// pernah menyentuh wrapper — bundle tiba (lewat putaran service
// worker) SETELAH modul YouTube memegang referensi fetch asli.
// Karena itu bundle kini didaftarkan sebagai content script
// MAIN world di document_start dari manifest: terpasang sebelum
// kode YouTube mana pun. Slot ini menjaga jalur fallback untuk
// tab yang sudah terbuka saat ekstensi di-install/update.
//
// slot.live: true bila terpasang saat document_start (readyState
// "loading"), atau setelah ada request /youtubei/v1/ yang terbukti
// melewati wrapper. Di luar itu hook dianggap belum live.

const HOOK_KEY = Symbol.for("aunucore.ytgift.hook");
const YOUTUBEI_RE = /\/youtubei\/v1\//;

function ensureHookSlot(win, fetchImpl) {
  if (!win || (typeof win !== "object" && typeof win !== "function")) return null;
  const existing = win[HOOK_KEY];
  if (existing) return existing;
  const originalFetch =
    fetchImpl ?? (typeof win.fetch === "function" ? win.fetch.bind(win) : undefined);
  if (typeof originalFetch !== "function") return null;
  const slot = {
    current: null,
    live: win.document?.readyState === "loading",
    originalFetch,
  };
  Object.defineProperty(win, HOOK_KEY, { value: slot });
  win.fetch = function (...args) {
    const s = win[HOOK_KEY];
    try {
      if (YOUTUBEI_RE.test(getRequestUrl(args[0]))) s.live = true;
    } catch { /* abaikan */ }
    return s.current ? s.current.fetch(...args) : s.originalFetch(...args);
  };
  return slot;
}

function getHookLive(win) {
  return Boolean(win?.[HOOK_KEY]?.live);
}

/**
 * @param {object} deps
 * @param {object}   [deps.win]           window target (default: window global)
 * @param {Function} [deps.fetchImpl]     fetch asli (untuk test/injeksi)
 * @param {object}   [deps.logger]        default: console
 * @param {Function} [deps.sleep]         penunda antar-retry (test: instan)
 * @param {number[]} [deps.retryDelaysMs] jadwal retry (default RETRY_DELAYS_MS)
 * @param {Function} [deps.onResult]      callback hasil akhir komentar GIF
 * @param {Function} [deps.teardown]      dipanggil bila salinan yang
 *   lebih baru mengambil alih hook (membersihkan listener/observer
 *   milik salinan ini)
 * @returns {Function} uninstall()
 */
function installFetchInterceptor(deps = {}) {
  const win = deps.win ?? (typeof window !== "undefined" ? window : globalThis);
  const slot = ensureHookSlot(win, deps.fetchImpl);
  if (!slot) return () => {};
  const originalFetch = slot.originalFetch;

  const logger = deps.logger ?? console;
  const sleep = deps.sleep ?? defaultSleep;
  const delays = deps.retryDelaysMs ?? RETRY_DELAYS_MS;

  const emitResult = (detail) => {
    if (typeof deps.onResult === "function") {
      try { deps.onResult(detail); } catch { /* abaikan */ }
    }
    if (win && typeof win.dispatchEvent === "function" && typeof win.CustomEvent === "function") {
      try {
        win.dispatchEvent(new win.CustomEvent("aunucore:gif-post-result", { detail }));
      } catch { /* abaikan */ }
    }
    if (detail.kind !== "posted") {
      // Cukup untuk membedakan kasus di laporan bug — tanpa teks
      // komentar, header, atau kredensial apa pun.
      logger.warn?.(`${LOG_PREFIX} komentar GIF tidak terkonfirmasi`, JSON.stringify(detail));
    }
  };

  const interceptedFetch = async (input, init = {}) => {
    const url = getRequestUrl(input);
    const method = getRequestMethod(input, init);

    if (!isCreateCommentRequest(url) || method !== "POST") {
      return originalFetch(input, init);
    }

    // Ambil body JSON: dari init.body, atau dari Request yang di-clone.
    let rawBody = typeof init.body === "string" ? init.body : undefined;
    let requestClone = null;

    if (rawBody === undefined && input && typeof input.clone === "function") {
      try {
        requestClone = input.clone();
        rawBody = await requestClone.text();
      } catch {
        rawBody = undefined;
      }
    }

    if (typeof rawBody !== "string" || !rawBody) {
      return originalFetch(input, init);
    }

    let parsed;
    try {
      parsed = JSON.parse(rawBody);
    } catch {
      return originalFetch(input, init); // bukan JSON -> jangan sentuh
    }

    const pending = getPendingGif();
    const ownTenorId = extractTenorId(parsed);
    if (!pending && !ownTenorId) {
      return originalFetch(input, init); // bukan komentar GIF -> lolos apa adanya
    }

    const { payload: nextPayload, armed } = applyGifToPayload(parsed, pending);
    if (pending && !armed) {
      // GIF dari mode tempel URL langsung: tidak punya id Tenor.
      logger.info?.(`${LOG_PREFIX} GIF non-Tenor tidak bisa dilampirkan; komentar dikirim sebagai teks`);
      return originalFetch(input, init);
    }

    const nextBody = JSON.stringify(nextPayload);
    const isRequestInput = Boolean(
      requestClone || (input && typeof input.clone === "function" && typeof init.body !== "string"),
    );
    const sendOnce = () =>
      isRequestInput
        ? originalFetch(new Request(input, { ...init, body: nextBody, method: "POST" }))
        : originalFetch(input, { ...init, body: nextBody });

    const tries = delays.length + 1;
    let attempt = 0;
    let response;
    let verdict;

    for (;;) {
      attempt++;
      try {
        response = await sendOnce();
      } catch (err) {
        emitResult({ ok: false, kind: "network", tries: attempt, tenorId: nextPayload.tenorId ?? null });
        throw err;
      }
      verdict = await judgeCommentResponse(response);
      if (verdict.kind !== "blocked" || attempt === tries) break;
      logger.info?.(`${LOG_PREFIX} YouTube menolak (blocked), mencoba lagi ${attempt + 1}/${tries}…`);
      await sleep(delays[attempt - 1]);
    }

    emitResult({
      ok: verdict.kind === "posted",
      kind: verdict.kind,
      tries: attempt,
      httpStatus: verdict.httpStatus,
      apiStatus: verdict.apiStatus,
      message: verdict.message,
      tenorId: nextPayload.tenorId ?? null,
    });

    // Pending dibersihkan hanya bila GIF-nya selesai urusannya:
    // terkirim, atau GIF-nya sendiri yang ditolak. Bila "blocked",
    // pending dipertahankan (dalam TTL) agar user bisa mencoba lagi.
    if (pending && (verdict.kind === "posted" || verdict.kind === "gif")) {
      setPendingGif(null);
      if (win && typeof win.dispatchEvent === "function" && typeof win.CustomEvent === "function") {
        win.dispatchEvent(new win.CustomEvent("aunucore:gif-cleared", { detail: null }));
      }
    }
    return response;
  };

  // Pensiunkan handler salinan sebelumnya, lalu daftarkan diri
  // sebagai handler aktif pada slot bersama.
  try { slot.current?.teardown?.(); } catch { /* abaikan */ }
  const handler = { fetch: interceptedFetch, teardown: deps.teardown };
  slot.current = handler;

  return function uninstall() {
    if (slot.current === handler) slot.current = null;
  };
}

// ---------------------------------------------------------------------------
// 6. Auto-install (browser saja, tidak jalan saat di-import oleh Node test)
// ---------------------------------------------------------------------------

if (typeof window !== "undefined" && typeof window.fetch === "function") {
  window.__AUNUCORE_YT_GIFT__ = {
    buildName: BUILD_NAME,
    phaseTestNumber: PHASE_TEST_NUMBER,
    // SENGAJA tidak ada field nama phase berikutnya di sini: field
    // seperti itu pernah membuat console seolah build berjalan adalah
    // phase lain. Objek ini hanya menyebut phase yang sedang aktif.
    pickerState,
    getPendingGif,
    get hookLive() { return getHookLive(window); },
  };

  // Picker (picker.js) mengumumkan GIF terpilih lewat CustomEvent.
  const onGifSelected = (e) => setPendingGif(e.detail);
  const onGifCleared = () => setPendingGif(null);
  window.addEventListener("aunucore:gif-selected", onGifSelected);
  window.addEventListener("aunucore:gif-cleared", onGifCleared);

  let teardownPicker = () => {};
  try {
    teardownPicker = initGifPicker({}) || (() => {});
  } catch (err) {
    console.warn(`${LOG_PREFIX} picker gagal dipasang:`, err);
  }

  // Phase test #5: interceptor kini tinggal di slot hook persisten
  // (lihat ensureHookSlot). Bila salinan bundle yang lebih baru
  // masuk ke halaman yang sama, teardown ini membersihkan listener
  // dan observer milik salinan ini.
  installFetchInterceptor({
    win: window,
    teardown: () => {
      window.removeEventListener("aunucore:gif-selected", onGifSelected);
      window.removeEventListener("aunucore:gif-cleared", onGifCleared);
      teardownPicker();
    },
  });

  const live = getHookLive(window);
  console.info(
    `${LOG_PREFIX} interceptor aktif di`,
    location.href,
    live ? "(hook live)" : "(hook BELUM live)",
  );
  if (!live) {
    console.warn(
      `${LOG_PREFIX} hook terpasang setelah halaman termuat — refresh tab ini agar pengiriman GIF bekerja`,
    );
  }
}
})();
